alter table public.lesson_blocks drop constraint if exists lesson_blocks_block_type_check;
alter table public.lesson_blocks add constraint lesson_blocks_block_type_check check (block_type in ('objective','text','concepts','formula','visual','examples','common_errors','tip','summary','video','practice','prerequisites','strategy','guided_practice','math_model'));

insert into public.learning_units (id,test_type,axis,slug,title,description,icon,sort_order,is_published) values ('school-5b-patrones-algebra','SCHOOL','Patrones y álgebra','5-basico-patrones-algebra','5.º básico · Patrones y álgebra','Reglas, sucesiones, ecuaciones e inecuaciones de un paso.','x',3,true) on conflict (id) do update set test_type=excluded.test_type,axis=excluded.axis,slug=excluded.slug,title=excluded.title,description=excluded.description,icon=excluded.icon,sort_order=excluded.sort_order,is_published=excluded.is_published;
