insert into public.lessons (id,unit_id,slug,title,summary,objective,estimated_minutes,difficulty,sort_order,is_published,video_url,thumbnail_url,prerequisites,tags,question_filter)
values
('school-5b-oa-14','school-5b-patrones-algebra','5b-reglas-sucesiones','Reglas y sucesiones','Descubre patrones, expresa reglas y predice términos o figuras sin depender solo de continuar manualmente.','Identificar la regularidad de una sucesión numérica o visual, comunicar su regla y utilizarla para predecir términos.',50,'Básico',1,true,null,null,'{}'::text[],array['5 básico','reglas y sucesiones']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-14", "topic_slug": "reglas-sucesiones"}'::jsonb),
('school-5b-oa-15','school-5b-patrones-algebra','5b-ecuaciones-inecuaciones-un-paso','Ecuaciones e inecuaciones de un paso','Representa cantidades desconocidas, resuelve igualdades y describe conjuntos de valores que cumplen una desigualdad.','Resolver y comprobar ecuaciones e inecuaciones de un paso asociadas a adiciones y sustracciones.',55,'Básico',2,true,null,null,array['school-5b-oa-14']::text[],array['5 básico','ecuaciones e inecuaciones de un paso']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-15", "topic_slug": "ecuaciones-e-inecuaciones-de-un-paso"}'::jsonb),
('school-5b-oa-16','school-5b-geometria','5b-plano-cartesiano','Plano cartesiano','Ubica, lee y desplaza puntos en el primer cuadrante utilizando pares ordenados.','Identificar coordenadas, dibujar puntos y describir desplazamientos horizontales y verticales en el primer cuadrante.',48,'Básico',1,true,null,null,'{}'::text[],array['5 básico','plano cartesiano']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-16", "topic_slug": "plano-cartesiano"}'::jsonb),
('school-5b-oa-17','school-5b-geometria','5b-paralelismo-perpendicularidad','Paralelismo y perpendicularidad','Reconoce y describe rectas paralelas, secantes y perpendiculares en figuras planas, objetos y cuerpos geométricos.','Distinguir relaciones entre rectas y justificar su clasificación a partir de intersecciones y ángulos.',45,'Básico',2,true,null,null,array['school-5b-oa-16']::text[],array['5 básico','paralelismo y perpendicularidad']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-17", "topic_slug": "paralelismo-perpendicularidad"}'::jsonb),
('school-5b-oa-18','school-5b-geometria','5b-congruencia-transformaciones','Congruencia y transformaciones','Comprende cómo traslaciones, reflexiones y rotaciones conservan forma y tamaño.','Reconocer y construir imágenes congruentes mediante transformaciones en cuadrículas.',55,'Básico',3,true,null,null,array['school-5b-oa-17']::text[],array['5 básico','congruencia y transformaciones']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-18", "topic_slug": "congruencia-transformaciones"}'::jsonb),
('school-5b-oa-19','school-5b-medicion','5b-medicion-longitudes','Medición de longitudes','Elige unidades e instrumentos adecuados, mide con precisión y comunica resultados.','Medir, estimar y comparar longitudes usando milímetros, centímetros y metros según el contexto.',46,'Básico',1,true,null,null,'{}'::text[],array['5 básico','medición de longitudes']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-19", "topic_slug": "medicion-de-longitudes"}'::jsonb),
('school-5b-oa-20','school-5b-medicion','5b-conversion-unidades-longitud','Conversión de unidades de longitud','Transforma longitudes entre kilómetros, metros, centímetros y milímetros manteniendo la misma cantidad.','Convertir unidades de longitud y resolver problemas que combinan escalas diferentes.',50,'Básico',2,true,null,null,array['school-5b-oa-19']::text[],array['5 básico','conversión de unidades de longitud']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-20", "topic_slug": "conversion-de-unidades-de-longitud"}'::jsonb),
('school-5b-oa-21','school-5b-medicion','5b-rectangulos-perimetro-area','Rectángulos, perímetro y área','Distingue borde y superficie, calcula medidas faltantes y analiza rectángulos con perímetro o área fija.','Diseñar y comparar rectángulos utilizando perímetro y área, extrayendo conclusiones sobre sus dimensiones.',56,'Básico',3,true,null,null,array['school-5b-oa-20']::text[],array['5 básico','rectángulos, perímetro y área']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-21", "topic_slug": "rectangulos-perimetro-area"}'::jsonb),
('school-5b-oa-22','school-5b-medicion','5b-areas-figuras','Áreas de figuras','Calcula áreas de triángulos, paralelogramos y trapecios mediante descomposición y transformación.','Derivar y aplicar relaciones de área, y estimar superficies de figuras compuestas o irregulares.',60,'Básico',4,true,null,null,array['school-5b-oa-21']::text[],array['5 básico','áreas de figuras']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-22", "topic_slug": "areas-de-figuras"}'::jsonb),
('school-5b-oa-23','school-5b-datos-probabilidad','5b-promedio-interpretacion','Promedio e interpretación','Calcula la media aritmética y la interpreta como reparto equitativo o punto de equilibrio.','Calcular promedios, reconstruir datos faltantes y comunicar qué representa el resultado.',52,'Básico',1,true,null,null,'{}'::text[],array['5 básico','promedio e interpretación']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-23", "topic_slug": "promedio-e-interpretacion"}'::jsonb),
('school-5b-oa-24','school-5b-datos-probabilidad','5b-posibilidad-ocurrencia','Posibilidad de ocurrencia','Clasifica eventos como seguros, posibles, poco posibles o imposibles según las condiciones de una experiencia aleatoria.','Describir cualitativamente la posibilidad de eventos y justificarla mediante resultados posibles.',44,'Básico',2,true,null,null,array['school-5b-oa-23']::text[],array['5 básico','posibilidad de ocurrencia']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-24", "topic_slug": "posibilidad-de-ocurrencia"}'::jsonb),
('school-5b-oa-25','school-5b-datos-probabilidad','5b-comparacion-probabilidades','Comparación cualitativa de probabilidades','Compara qué evento es más, menos o igualmente probable usando composición y proporción de resultados.','Ordenar probabilidades cualitativamente sin depender necesariamente de un cálculo formal.',48,'Básico',3,true,null,null,array['school-5b-oa-24']::text[],array['5 básico','comparación cualitativa de probabilidades']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-25", "topic_slug": "comparacion-cualitativa-de-probabilidades"}'::jsonb),
('school-5b-oa-26','school-5b-datos-probabilidad','5b-tablas-graficos','Tablas y gráficos','Lee, completa y comunica información de tablas, gráficos de barras y gráficos de líneas.','Interpretar datos, calcular cambios y formular conclusiones respaldadas por representaciones gráficas.',54,'Básico',4,true,null,null,array['school-5b-oa-25']::text[],array['5 básico','tablas y gráficos']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-26", "topic_slug": "tablas-graficos"}'::jsonb),
('school-5b-oa-27','school-5b-datos-probabilidad','5b-diagramas-tallo-hojas','Diagramas de tallo y hojas','Construye e interpreta diagramas de tallo y hojas conservando cada dato original.','Organizar datos numéricos en tallos y hojas, recuperar valores y analizar distribución, extremos y rango.',50,'Básico',5,true,null,null,array['school-5b-oa-26']::text[],array['5 básico','diagramas de tallo y hojas']::text[],'{"course_id": "cl-5-basico", "topic_id": "topic-ma05-oa-27", "topic_slug": "diagramas-de-tallo-hojas"}'::jsonb)
on conflict (id) do update set unit_id=excluded.unit_id,slug=excluded.slug,title=excluded.title,summary=excluded.summary,objective=excluded.objective,estimated_minutes=excluded.estimated_minutes,difficulty=excluded.difficulty,sort_order=excluded.sort_order,is_published=excluded.is_published,prerequisites=excluded.prerequisites,tags=excluded.tags,question_filter=excluded.question_filter;

delete from public.lesson_blocks where lesson_id in ('school-5b-oa-14','school-5b-oa-15','school-5b-oa-16','school-5b-oa-17','school-5b-oa-18','school-5b-oa-19','school-5b-oa-20','school-5b-oa-21','school-5b-oa-22','school-5b-oa-23','school-5b-oa-24','school-5b-oa-25','school-5b-oa-26','school-5b-oa-27');
insert into public.lesson_blocks (lesson_id,block_type,title,content,data,sort_order)
select lesson_id,block_type,title,content,data,sort_order
from jsonb_to_recordset($blocks$[{"lesson_id":"school-5b-oa-14","block_type":"objective","title":"Meta de aprendizaje","content":"Identificar la regularidad de una sucesión numérica o visual, comunicar su regla y utilizarla para predecir términos.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-14","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Operaciones básicas","body":"Las diferencias y productos ayudan a reconocer cómo cambia una sucesión."},{"title":"Orden","body":"Cada término ocupa una posición: primero, segundo, tercero, etc."},{"title":"Tablas","body":"Una tabla permite relacionar número de paso y cantidad obtenida."}]},"sort_order":2},{"lesson_id":"school-5b-oa-14","block_type":"text","title":"Comprensión profunda","content":"Una sucesión es una lista ordenada de números, figuras u objetos que sigue una regla. La regla debe funcionar en todos los pasos observados, no solamente entre dos términos.\n\nEn sucesiones aditivas, la misma cantidad se suma o resta en cada paso. También pueden aparecer reglas que duplican, combinan operaciones o dependen del número de la posición. Para predecir términos lejanos conviene relacionar el número de paso con el valor del término, en vez de repetir la regla muchas veces.\n\nUna regla puede comunicarse con palabras, una tabla, un diagrama o una expresión. Para validarla, se usa en varios términos conocidos y se comprueba que todos coincidan.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-14","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Término","body":"Cada elemento de la sucesión."},{"title":"Posición","body":"Lugar que ocupa el término dentro de la sucesión."},{"title":"Regla recursiva","body":"Explica cómo obtener un término a partir del anterior."},{"title":"Regla por posición","body":"Relaciona directamente el número del paso con el término."}]},"sort_order":4},{"lesson_id":"school-5b-oa-14","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"sequence_path","values":[4,9,14,19,24],"rule":"Sumar 5","caption":"La diferencia constante permite anticipar los términos siguientes."},"sort_order":5},{"lesson_id":"school-5b-oa-14","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Regla aditiva: término siguiente = término anterior + diferencia","Desde el término 1 al término n hay n−1 cambios","Comprueba una regla en al menos tres términos","Una tabla puede relacionar paso y cantidad","La predicción debe conservar la misma regularidad"]},"sort_order":6},{"lesson_id":"school-5b-oa-14","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Observa cambios","body":"Calcula diferencias o compara cómo crece la figura."},{"title":"2. Propón una regla","body":"Exprésala con una operación clara."},{"title":"3. Verifica","body":"Prueba la regla en todos los términos disponibles."},{"title":"4. Predice","body":"Aplica la regla las veces necesarias o usa la posición."},{"title":"5. Comunica","body":"Explica qué cambia y qué permanece constante."}]},"sort_order":7},{"lesson_id":"school-5b-oa-14","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Continúa 6, 10, 14, 18, …","steps":["Las diferencias son 4, 4 y 4.","La regla es sumar 4.","18+4=22."],"answer":"22","skill":"Resolver problemas","level":"Fundamental","strategy":"Busca la diferencia entre términos consecutivos.","verification":"22−18=4, igual a las diferencias anteriores."},{"problem":"¿Cuál es el término anterior a 35 en la sucesión que aumenta de 7 en 7?","steps":["La operación inversa de sumar 7 es restar 7.","35−7=28."],"answer":"28","skill":"Resolver problemas","level":"Fundamental","strategy":"Trabaja hacia atrás con la operación inversa.","verification":"28+7=35."}]},"sort_order":8},{"lesson_id":"school-5b-oa-14","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"La sucesión comienza en 5 y aumenta 3. ¿Cuál es el sexto término?","steps":["El primer término ya es 5.","Hasta el sexto hay 5 aumentos.","5+5·3=20."],"answer":"20","skill":"Modelar","level":"Intermedio","strategy":"Cuenta cambios, no términos.","verification":"5, 8, 11, 14, 17, 20."},{"problem":"Una figura usa 4 palitos en el paso 1 y agrega 3 por paso. ¿Cuántos palitos hay en el paso 8?","steps":["Desde el paso 1 al 8 hay 7 aumentos.","7·3=21.","4+21=25."],"answer":"25 palitos","skill":"Modelar","level":"Intermedio","strategy":"Separa cantidad inicial y crecimiento.","verification":"En el paso 2 habría 7, coherente con agregar 3."}]},"sort_order":9},{"lesson_id":"school-5b-oa-14","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Determina la regla por posición de 7, 11, 15, 19, …","steps":["La diferencia es 4.","Multiplicar la posición por 4 produce 4,8,12,16.","Faltan 3 unidades en cada término."],"answer":"Multiplicar la posición por 4 y sumar 3","skill":"Argumentar","level":"Desafío","strategy":"Compara los términos con múltiplos de la diferencia.","verification":"Para posición 4: 4·4+3=19."},{"problem":"¿Puede la regla “sumar 4” describir 3, 7, 11, 16?","steps":["3→7 aumenta 4.","7→11 aumenta 4.","11→16 aumenta 5."],"answer":"No; el último cambio rompe la regla","skill":"Argumentar","level":"Desafío","strategy":"Una regla debe funcionar en todos los pasos.","verification":"Si fuera sumar 4, el cuarto término sería 15."}]},"sort_order":10},{"lesson_id":"school-5b-oa-14","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Continúa 42, 36, 30, 24, …","hints":["Calcula la diferencia.","La sucesión disminuye siempre lo mismo."],"steps":["42−36=6.","24−6=18."],"answer":"18","skill":"Resolver problemas"},{"problem":"Una sucesión parte en 2 y aumenta 5. ¿Cuál es el séptimo término?","hints":["Desde el primero al séptimo hay 6 cambios.","Multiplica 6 por 5."],"steps":["6·5=30.","2+30=32."],"answer":"32","skill":"Modelar"},{"problem":"Paso 1: 5 puntos; paso 2: 8; paso 3: 11. Explica la regla.","hints":["Compara cada par consecutivo.","Indica cantidad inicial y crecimiento."],"steps":["Cada paso agrega 3 puntos.","La regla por posición puede expresarse como 3·paso+2."],"answer":"Agregar 3 en cada paso","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-14","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Mirar solo los últimos dos términos","description":"La regla debe comprobarse en todos los datos."},{"title":"Contar n aumentos para llegar al término n","description":"Desde el primero al término n hay n−1 cambios."},{"title":"Confundir posición con valor","description":"El paso 5 no significa que el término valga 5."},{"title":"Describir sin precisar","description":"“Va aumentando” no comunica cuánto aumenta."}]},"sort_order":12},{"lesson_id":"school-5b-oa-14","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Reconoces diferencias y regularidades.","Expresas reglas con palabras y tablas.","Predices términos cercanos y lejanos.","Relacionas posición y valor.","Compruebas si una regla es válida."]},"sort_order":13},{"lesson_id":"school-5b-oa-14","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-15","block_type":"objective","title":"Meta de aprendizaje","content":"Resolver y comprobar ecuaciones e inecuaciones de un paso asociadas a adiciones y sustracciones.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-15","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Operaciones inversas","body":"Sumar y restar permiten deshacer una transformación."},{"title":"Igualdad","body":"El signo = afirma que ambos lados representan la misma cantidad."},{"title":"Orden numérico","body":"Los signos < y > comparan valores."}]},"sort_order":2},{"lesson_id":"school-5b-oa-15","block_type":"text","title":"Comprensión profunda","content":"Una ecuación es una igualdad que contiene una cantidad desconocida. Resolverla significa encontrar el valor que hace verdadera la igualdad. La idea de equilibrio es central: cualquier transformación válida debe conservar la misma cantidad en ambos lados.\n\nEn una ecuación de un paso, la operación que acompaña a la incógnita se deshace mediante su operación inversa. La comprobación consiste en reemplazar la incógnita por el valor hallado.\n\nUna inecuación no suele tener una sola solución, sino varios valores. Por ejemplo, x+3<8 se cumple para números menores que 5. Es importante distinguir una frontera incluida (≤ o ≥) de una frontera excluida (< o >).","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-15","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Incógnita","body":"Símbolo que representa un valor desconocido."},{"title":"Solución","body":"Valor que hace verdadera la ecuación o inecuación."},{"title":"Operación inversa","body":"Deshace la operación aplicada a la incógnita."},{"title":"Conjunto de soluciones","body":"Todos los valores que cumplen una inecuación."}]},"sort_order":4},{"lesson_id":"school-5b-oa-15","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"balance_scale","left":"x + 7","right":"19","operation":"Restar 7 a ambos lados","result":"x = 12","caption":"Mantener el equilibrio exige realizar la misma transformación en ambos lados."},"sort_order":5},{"lesson_id":"school-5b-oa-15","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["x+a=b  →  x=b−a","x−a=b  →  x=b+a","Comprueba reemplazando x","x+a<b  →  valores de x menores que b−a","La frontera se incluye solo con ≤ o ≥"]},"sort_order":6},{"lesson_id":"school-5b-oa-15","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Traduce","body":"Representa la situación con una igualdad o desigualdad."},{"title":"2. Identifica la operación","body":"Observa qué se hizo con la incógnita."},{"title":"3. Aplica la inversa","body":"Deshaz la operación conservando el equilibrio."},{"title":"4. Interpreta","body":"En inecuaciones, describe todos los valores posibles."},{"title":"5. Comprueba","body":"Sustituye un valor y revisa la afirmación."}]},"sort_order":7},{"lesson_id":"school-5b-oa-15","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Resuelve x+8=23.","steps":["Restamos 8 a ambos lados.","x=23−8."],"answer":"x=15","skill":"Resolver problemas","level":"Fundamental","strategy":"Deshaz la suma con una resta.","verification":"15+8=23."},{"problem":"Resuelve x−12=19.","steps":["Sumamos 12 a ambos lados.","x=19+12."],"answer":"x=31","skill":"Resolver problemas","level":"Fundamental","strategy":"Deshaz la resta sumando.","verification":"31−12=19."}]},"sort_order":8},{"lesson_id":"school-5b-oa-15","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"En una caja había cierta cantidad. Al agregar 17 hay 45. ¿Cuántos había?","steps":["Sea x la cantidad inicial.","x+17=45.","x=45−17=28."],"answer":"28 objetos","skill":"Modelar","level":"Intermedio","strategy":"Define primero qué representa x.","verification":"28+17=45."},{"problem":"Resuelve n+5<12 para números naturales.","steps":["Restamos 5 a la frontera.","n<7.","Los naturales posibles menores que 7 son 0,1,2,3,4,5,6."],"answer":"n<7","skill":"Argumentar","level":"Intermedio","strategy":"Una inecuación describe varios valores.","verification":"6+5=11 cumple; 7+5=12 no cumple <12."}]},"sort_order":9},{"lesson_id":"school-5b-oa-15","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"¿Es x=14 solución de x−6>9?","steps":["Sustituimos 14.","14−6=8.","8 no es mayor que 9."],"answer":"No","skill":"Argumentar","level":"Desafío","strategy":"Comprobar evita aceptar valores incorrectos.","verification":"Para cumplir, x tendría que ser mayor que 15."},{"problem":"Un estudiante resuelve x+9=20 y obtiene x=29. Explica el error.","steps":["Sumó 9 en vez de deshacer la suma.","La operación inversa correcta es restar 9.","20−9=11."],"answer":"x=11","skill":"Argumentar","level":"Desafío","strategy":"Nombra la operación y su inversa.","verification":"11+9=20."}]},"sort_order":10},{"lesson_id":"school-5b-oa-15","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Resuelve y+13=40.","hints":["Usa la operación inversa.","Calcula 40−13."],"steps":["Restamos 13.","y=27."],"answer":"y=27","skill":"Resolver problemas"},{"problem":"Resuelve m−9=26.","hints":["Deshaz la resta.","Suma 9."],"steps":["m=26+9.","m=35."],"answer":"m=35","skill":"Resolver problemas"},{"problem":"Describe los naturales que cumplen p+4≤9.","hints":["Resta 4 a la frontera.","El símbolo ≤ incluye el límite."],"steps":["p≤5.","Posibles: 0,1,2,3,4,5."],"answer":"p≤5","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-15","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Cambiar solo un lado","description":"Rompe la igualdad; la transformación debe conservar el equilibrio."},{"title":"Usar la misma operación en vez de la inversa","description":"Para deshacer +7 se resta 7."},{"title":"Dar una sola solución a una inecuación","description":"Normalmente hay varios valores que cumplen."},{"title":"No comprobar","description":"Sustituir la respuesta detecta errores rápidamente."}]},"sort_order":12},{"lesson_id":"school-5b-oa-15","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Traducir situaciones a ecuaciones.","Resolver ecuaciones de adición y sustracción.","Comprobar soluciones.","Describir soluciones de inecuaciones.","Interpretar signos de comparación."]},"sort_order":13},{"lesson_id":"school-5b-oa-15","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-16","block_type":"objective","title":"Meta de aprendizaje","content":"Identificar coordenadas, dibujar puntos y describir desplazamientos horizontales y verticales en el primer cuadrante.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-16","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Recta numérica","body":"Cada eje contiene valores que aumentan desde el origen."},{"title":"Direcciones","body":"Derecha modifica x; arriba modifica y."},{"title":"Pares ordenados","body":"El orden de las coordenadas no puede intercambiarse."}]},"sort_order":2},{"lesson_id":"school-5b-oa-16","block_type":"text","title":"Comprensión profunda","content":"El plano cartesiano permite describir posiciones mediante dos ejes perpendiculares. En el primer cuadrante, las coordenadas son números naturales o cero.\n\nUn punto se escribe (x,y). La primera coordenada indica el desplazamiento horizontal desde el origen y la segunda el desplazamiento vertical. Por eso (2,5) y (5,2) representan puntos diferentes.\n\nAl trasladar un punto horizontalmente cambia x y permanece y; al trasladarlo verticalmente cambia y y permanece x. Estas relaciones permiten describir rutas, mapas y figuras.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-16","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Origen","body":"Punto (0,0) donde se cruzan los ejes."},{"title":"Eje x","body":"Eje horizontal."},{"title":"Eje y","body":"Eje vertical."},{"title":"Par ordenado","body":"Coordenadas escritas siempre como (x,y)."}]},"sort_order":4},{"lesson_id":"school-5b-oa-16","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"coordinate_plane","points":[{"x":2,"y":5,"label":"A"},{"x":6,"y":2,"label":"B"},{"x":4,"y":4,"label":"C"}],"caption":"Primero se avanza horizontalmente y luego verticalmente."},"sort_order":5},{"lesson_id":"school-5b-oa-16","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["P=(x,y)","Derecha: x aumenta","Izquierda: x disminuye","Arriba: y aumenta","Abajo: y disminuye"]},"sort_order":6},{"lesson_id":"school-5b-oa-16","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Parte del origen","body":"Ubica (0,0)."},{"title":"2. Lee x","body":"Desplázate horizontalmente."},{"title":"3. Lee y","body":"Desplázate verticalmente."},{"title":"4. Marca y nombra","body":"Comprueba el par ordenado."},{"title":"5. Describe movimientos","body":"Indica dirección, unidades y coordenada que cambia."}]},"sort_order":7},{"lesson_id":"school-5b-oa-16","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Ubica el punto (4,2).","steps":["Desde el origen avanza 4 a la derecha.","Luego sube 2."],"answer":"4 a la derecha y 2 arriba","skill":"Representar","level":"Fundamental","strategy":"Lee siempre x antes que y.","verification":"El punto queda en el primer cuadrante."},{"problem":"¿Qué coordenadas tiene un punto ubicado 3 a la derecha y 6 arriba?","steps":["El desplazamiento horizontal es x=3.","El vertical es y=6."],"answer":"(3,6)","skill":"Representar","level":"Fundamental","strategy":"Traduce direcciones a coordenadas.","verification":"Desde (0,0) se llega a (3,6)."}]},"sort_order":8},{"lesson_id":"school-5b-oa-16","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"A=(2,5) se traslada 3 unidades a la derecha.","steps":["Aumenta x en 3.","y permanece en 5.","2+3=5."],"answer":"(5,5)","skill":"Modelar","level":"Intermedio","strategy":"Un movimiento horizontal modifica solo x.","verification":"La distancia horizontal entre ambos puntos es 3."},{"problem":"B=(7,4) baja 2 unidades.","steps":["x permanece en 7.","y disminuye 2.","4−2=2."],"answer":"(7,2)","skill":"Modelar","level":"Intermedio","strategy":"Un movimiento vertical modifica solo y.","verification":"Desde (7,2), subir 2 vuelve a (7,4)."}]},"sort_order":9},{"lesson_id":"school-5b-oa-16","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Tres vértices de un rectángulo son (1,1), (6,1) y (6,4). ¿Cuál es el cuarto?","steps":["Los lados horizontales conservan y.","Los lados verticales conservan x.","Falta combinar x=1 con y=4."],"answer":"(1,4)","skill":"Argumentar","level":"Desafío","strategy":"Busca coordenadas compartidas por lados paralelos.","verification":"Forma lados de longitudes 5 y 3."},{"problem":"Un alumno ubica (2,7) avanzando 7 a la derecha y 2 arriba. Explica.","steps":["Intercambió las coordenadas.","La primera coordenada es horizontal.","Debe avanzar 2 a la derecha y 7 arriba."],"answer":"La ubicación correcta usa x=2, y=7","skill":"Argumentar","level":"Desafío","strategy":"Explica el significado del orden.","verification":"Su procedimiento ubicó realmente (7,2)."}]},"sort_order":10},{"lesson_id":"school-5b-oa-16","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Ubica P=(5,3).","hints":["La primera coordenada es horizontal.","La segunda es vertical."],"steps":["Avanza 5 a la derecha.","Sube 3."],"answer":"(5,3)","skill":"Representar"},{"problem":"Q=(4,6) se mueve 2 a la izquierda.","hints":["Solo cambia x.","Resta 2 a 4."],"steps":["4−2=2.","y sigue siendo 6."],"answer":"(2,6)","skill":"Modelar"},{"problem":"¿Qué punto está sobre la misma línea horizontal que (3,5): (7,5) o (3,7)?","hints":["Una línea horizontal conserva y.","Compara la segunda coordenada."],"steps":["(7,5) también tiene y=5."],"answer":"(7,5)","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-16","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Intercambiar x e y","description":"(2,5) no es lo mismo que (5,2)."},{"title":"Modificar ambas coordenadas","description":"Un movimiento puramente horizontal o vertical cambia solo una."},{"title":"Comenzar fuera del origen","description":"Las coordenadas se miden desde (0,0)."},{"title":"Omitir el orden del desplazamiento","description":"Primero se interpreta x y después y."}]},"sort_order":12},{"lesson_id":"school-5b-oa-16","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Lees pares ordenados.","Ubicas puntos en el primer cuadrante.","Describes desplazamientos.","Construyes figuras con coordenadas.","Justificas qué coordenada cambia."]},"sort_order":13},{"lesson_id":"school-5b-oa-16","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-17","block_type":"objective","title":"Meta de aprendizaje","content":"Distinguir relaciones entre rectas y justificar su clasificación a partir de intersecciones y ángulos.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-17","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Rectas y segmentos","body":"Una recta se extiende; un segmento tiene extremos."},{"title":"Ángulo recto","body":"Mide 90° y suele marcarse con un cuadrado."},{"title":"Intersección","body":"Punto donde dos líneas se cruzan."}]},"sort_order":2},{"lesson_id":"school-5b-oa-17","block_type":"text","title":"Comprensión profunda","content":"Dos rectas son paralelas cuando mantienen siempre la misma distancia y no se intersectan en el plano. Dos rectas son secantes cuando se cruzan. Si al cruzarse forman cuatro ángulos rectos, son perpendiculares.\n\nToda pareja de rectas perpendiculares es secante, pero no toda pareja secante es perpendicular. Esta distinción permite describir lados de polígonos, aristas de cuerpos, calles y estructuras.\n\nLa clasificación debe basarse en propiedades, no solo en la apariencia de un dibujo. Una figura inclinada puede conservar paralelismo y perpendicularidad.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-17","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Paralelas","body":"No se cruzan y conservan distancia."},{"title":"Secantes","body":"Se intersectan en un punto."},{"title":"Perpendiculares","body":"Se intersectan formando 90°."},{"title":"Aristas","body":"Segmentos donde se encuentran caras de un cuerpo."}]},"sort_order":4},{"lesson_id":"school-5b-oa-17","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"line_relationships","caption":"Las paralelas no se cruzan; las perpendiculares forman un ángulo recto."},"sort_order":5},{"lesson_id":"school-5b-oa-17","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Paralelas: misma dirección, sin intersección","Secantes: una intersección","Perpendiculares: secantes con ángulo de 90°","Perpendiculares ⊂ secantes","La inclinación del dibujo no cambia la relación"]},"sort_order":6},{"lesson_id":"school-5b-oa-17","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Extiende mentalmente","body":"Pregunta si las líneas llegarían a cruzarse."},{"title":"2. Busca intersección","body":"Si no existe, pueden ser paralelas."},{"title":"3. Revisa el ángulo","body":"Si es 90°, son perpendiculares."},{"title":"4. Nombra con precisión","body":"Evita usar “cruzadas” sin clasificar."},{"title":"5. Justifica","body":"Menciona distancia, intersección o ángulo."}]},"sort_order":7},{"lesson_id":"school-5b-oa-17","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Los lados opuestos de un rectángulo, ¿qué relación tienen?","steps":["Cada par de lados opuestos mantiene la misma dirección.","No se intersectan."],"answer":"Son paralelos","skill":"Argumentar","level":"Fundamental","strategy":"Observa pares opuestos.","verification":"Al prolongarlos, no se cruzan."},{"problem":"Un lado horizontal y uno vertical de un cuadrado se encuentran.","steps":["Se intersectan.","Forman un ángulo recto."],"answer":"Son perpendiculares","skill":"Argumentar","level":"Fundamental","strategy":"Busca la marca o forma del ángulo recto.","verification":"Un cuadrado tiene cuatro ángulos de 90°."}]},"sort_order":8},{"lesson_id":"school-5b-oa-17","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Dos calles se cruzan formando un ángulo que no es recto.","steps":["Existe intersección.","No forman 90°."],"answer":"Son secantes, no perpendiculares","skill":"Modelar","level":"Intermedio","strategy":"Toda intersección no implica perpendicularidad.","verification":"La clasificación usa el ángulo."},{"problem":"¿Pueden dos rectas paralelas tener un punto común en el plano?","steps":["La definición exige que no se intersecten.","Un punto común sería una intersección."],"answer":"No","skill":"Argumentar","level":"Intermedio","strategy":"Usa directamente la definición.","verification":"Si se cruzaran dejarían de ser paralelas."}]},"sort_order":9},{"lesson_id":"school-5b-oa-17","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"En un cubo, una arista vertical y una arista horizontal que comparten vértice.","steps":["Comparten un extremo.","Las caras del cubo tienen ángulos rectos."],"answer":"Son perpendiculares","skill":"Representar","level":"Desafío","strategy":"Relaciona el cuerpo con sus caras cuadradas.","verification":"Forman 90° en la cara correspondiente."},{"problem":"Un rombo inclinado tiene lados opuestos. ¿Son paralelos?","steps":["La inclinación global no cambia las direcciones relativas.","Los lados opuestos no se cruzan."],"answer":"Sí, son paralelos","skill":"Argumentar","level":"Desafío","strategy":"No dependas de que las líneas sean horizontales.","verification":"Todo paralelogramo tiene lados opuestos paralelos."}]},"sort_order":10},{"lesson_id":"school-5b-oa-17","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Dos líneas nunca se cruzan y conservan distancia. Clasifica.","hints":["Piensa en la definición de paralelas."],"steps":["No existe intersección.","La distancia se mantiene."],"answer":"Paralelas","skill":"Argumentar"},{"problem":"Dos líneas se cruzan formando cuatro ángulos rectos.","hints":["Son secantes, pero existe una clasificación más específica."],"steps":["Forman 90°."],"answer":"Perpendiculares","skill":"Argumentar"},{"problem":"¿Toda pareja perpendicular es secante?","hints":["Las perpendiculares se cruzan.","Secante significa que existe intersección."],"steps":["Sí, se intersectan en un punto."],"answer":"Sí","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-17","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Confundir paralelas con líneas horizontales","description":"Las paralelas también pueden estar inclinadas."},{"title":"Llamar perpendiculares a todas las secantes","description":"Solo lo son si forman 90°."},{"title":"Mirar segmentos muy cortos","description":"Conviene imaginar las rectas prolongadas."},{"title":"Clasificar solo por apariencia","description":"La propiedad geométrica debe justificar la respuesta."}]},"sort_order":12},{"lesson_id":"school-5b-oa-17","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Distingues paralelas, secantes y perpendiculares.","Reconoces ángulos rectos.","Clasificas lados y aristas.","No dependes de la orientación del dibujo.","Justificas usando propiedades."]},"sort_order":13},{"lesson_id":"school-5b-oa-17","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-18","block_type":"objective","title":"Meta de aprendizaje","content":"Reconocer y construir imágenes congruentes mediante transformaciones en cuadrículas.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-18","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Coordenadas y cuadrículas","body":"Permiten describir movimientos con precisión."},{"title":"Longitudes y ángulos","body":"La congruencia conserva ambos."},{"title":"Direcciones","body":"Trasladar, reflejar y girar producen movimientos distintos."}]},"sort_order":2},{"lesson_id":"school-5b-oa-18","block_type":"text","title":"Comprensión profunda","content":"Dos figuras son congruentes cuando tienen la misma forma y el mismo tamaño, aunque estén en distinta posición u orientación.\n\nUna traslación desplaza todos los puntos la misma distancia y dirección. Una reflexión produce una imagen espejo respecto de una línea. Una rotación gira la figura alrededor de un centro por un ángulo y sentido determinados.\n\nEstas transformaciones conservan distancias, ángulos, perímetro y área. Para comprobar una construcción se puede comparar cada vértice y verificar que todos obedecen la misma transformación.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-18","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Congruencia","body":"Igual forma e igual tamaño."},{"title":"Traslación","body":"Desplazamiento uniforme sin girar."},{"title":"Reflexión","body":"Imagen espejo respecto de un eje."},{"title":"Rotación","body":"Giro alrededor de un centro."}]},"sort_order":4},{"lesson_id":"school-5b-oa-18","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"transformation_grid","shape":[[2,2],[4,2],[3,4]],"translation":[4,1],"caption":"Todos los vértices se desplazan con el mismo vector, por lo que la figura conserva sus medidas."},"sort_order":5},{"lesson_id":"school-5b-oa-18","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Traslación: (x,y)→(x+a,y+b)","Reflexión conserva distancia al eje","Rotación conserva distancia al centro","Congruencia conserva lados y ángulos","Perímetro y área no cambian"]},"sort_order":6},{"lesson_id":"school-5b-oa-18","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica la transformación","body":"¿Se desliza, refleja o gira?"},{"title":"2. Ubica referencia","body":"Dirección, eje o centro."},{"title":"3. Mueve cada vértice","body":"Aplica exactamente la misma regla."},{"title":"4. Une en el mismo orden","body":"Conserva la correspondencia entre vértices."},{"title":"5. Verifica congruencia","body":"Compara longitudes y ángulos."}]},"sort_order":7},{"lesson_id":"school-5b-oa-18","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Traslada A=(2,3) cuatro unidades a la derecha.","steps":["Aumenta x en 4.","y permanece en 3."],"answer":"A′=(6,3)","skill":"Representar","level":"Fundamental","strategy":"Una traslación horizontal cambia solo x.","verification":"La distancia entre A y A′ es 4."},{"problem":"Una figura se refleja y cambia de orientación, pero mantiene medidas. ¿Es congruente?","steps":["La reflexión conserva longitudes y ángulos.","La orientación espejo no cambia el tamaño."],"answer":"Sí","skill":"Argumentar","level":"Fundamental","strategy":"Congruente no significa misma orientación.","verification":"Ambas figuras pueden superponerse mediante una reflexión."}]},"sort_order":8},{"lesson_id":"school-5b-oa-18","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Traslada el triángulo (1,1),(4,1),(2,3) dos arriba.","steps":["Aumentamos y en 2 para cada vértice.","x permanece."],"answer":"(1,3),(4,3),(2,5)","skill":"Representar","level":"Intermedio","strategy":"Aplica la regla a todos los puntos.","verification":"Cada vértice subió exactamente 2."},{"problem":"Una rotación de 90° cambia el área de un cuadrado de 16 u²?","steps":["La rotación es un movimiento rígido.","Conserva longitudes y área."],"answer":"No; sigue siendo 16 u²","skill":"Argumentar","level":"Intermedio","strategy":"Distingue posición de tamaño.","verification":"El lado conserva su longitud 4."}]},"sort_order":9},{"lesson_id":"school-5b-oa-18","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Una copia aumenta todos los lados al doble. ¿Es congruente con el original?","steps":["La forma se conserva.","El tamaño cambia.","Congruencia exige misma forma y tamaño."],"answer":"No; es semejante, pero no congruente","skill":"Argumentar","level":"Desafío","strategy":"Comprueba ambas condiciones.","verification":"El perímetro y área cambiaron."},{"problem":"¿Cómo comprobar una reflexión respecto de una línea vertical?","steps":["Cada punto y su imagen deben estar a igual distancia del eje.","Deben ubicarse a lados opuestos sobre una perpendicular al eje."],"answer":"Comparando distancias iguales al eje","skill":"Argumentar","level":"Desafío","strategy":"Usa la línea de reflexión como mediatriz.","verification":"El punto medio del segmento punto-imagen queda en el eje."}]},"sort_order":10},{"lesson_id":"school-5b-oa-18","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Traslada (5,2) tres unidades arriba.","hints":["Solo cambia y.","Suma 3."],"steps":["2+3=5.","x sigue en 5."],"answer":"(5,5)","skill":"Representar"},{"problem":"¿Una reflexión conserva el perímetro?","hints":["Revisa si cambian las longitudes."],"steps":["Las longitudes no cambian.","La suma de los lados permanece."],"answer":"Sí","skill":"Argumentar"},{"problem":"Una figura gira pero uno de sus vértices queda a distinta distancia del centro. ¿Es una rotación correcta?","hints":["En una rotación cada punto conserva su distancia al centro."],"steps":["La distancia cambió, por lo tanto la construcción es incorrecta."],"answer":"No","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-18","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Mover solo algunos vértices","description":"La misma transformación debe aplicarse a toda la figura."},{"title":"Confundir congruencia con misma orientación","description":"Una figura reflejada puede ser congruente."},{"title":"Cambiar el tamaño durante el movimiento","description":"Las transformaciones rígidas conservan medidas."},{"title":"No indicar eje o centro","description":"Una reflexión o rotación necesita una referencia clara."}]},"sort_order":12},{"lesson_id":"school-5b-oa-18","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Reconoces figuras congruentes.","Construyes traslaciones.","Interpretas reflexiones y rotaciones.","Identificas propiedades conservadas.","Compruebas transformaciones por vértices."]},"sort_order":13},{"lesson_id":"school-5b-oa-18","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-19","block_type":"objective","title":"Meta de aprendizaje","content":"Medir, estimar y comparar longitudes usando milímetros, centímetros y metros según el contexto.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-19","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Unidades de longitud","body":"Cada unidad sirve para escalas distintas."},{"title":"Regla graduada","body":"Las marcas indican intervalos iguales."},{"title":"Resta","body":"La longitud de un segmento puede obtenerse con final−inicio."}]},"sort_order":2},{"lesson_id":"school-5b-oa-19","block_type":"text","title":"Comprensión profunda","content":"Medir una longitud consiste en compararla con una unidad. La elección de unidad influye en la claridad: milímetros para objetos muy pequeños, centímetros para objetos de uso cotidiano y metros para distancias mayores.\n\nUna medición comienza en la marca cero del instrumento. Si un objeto comienza en otra marca, su longitud se calcula restando la lectura inicial a la final.\n\nToda medición tiene una precisión limitada por el instrumento. Por eso es importante registrar la unidad y distinguir una estimación de una medición directa.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-19","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Unidad","body":"Cantidad patrón usada para medir."},{"title":"Instrumento","body":"Regla, huincha u otro dispositivo graduado."},{"title":"Precisión","body":"Nivel de detalle que permite la graduación."},{"title":"Estimación","body":"Valor aproximado razonable antes de medir."}]},"sort_order":4},{"lesson_id":"school-5b-oa-19","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"ruler_measurement","start":2.3,"end":8.7,"unit":"cm","caption":"La longitud corresponde a lectura final menos lectura inicial."},"sort_order":5},{"lesson_id":"school-5b-oa-19","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Longitud = lectura final − lectura inicial","1 cm contiene 10 mm","Registra siempre número y unidad","Usa una unidad acorde al tamaño","Estima antes de medir"]},"sort_order":6},{"lesson_id":"school-5b-oa-19","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Estima","body":"Anticipa un rango razonable."},{"title":"2. Elige unidad","body":"Evita números incómodos o imprecisos."},{"title":"3. Alinea el instrumento","body":"Usa el cero o registra la marca inicial."},{"title":"4. Lee perpendicularmente","body":"Reduce errores de observación."},{"title":"5. Comunica","body":"Escribe valor, unidad y si es aproximado."}]},"sort_order":7},{"lesson_id":"school-5b-oa-19","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"¿Qué unidad usarías para el grosor de una moneda?","steps":["Es una longitud pequeña.","El milímetro ofrece precisión adecuada."],"answer":"Milímetros","skill":"Argumentar","level":"Fundamental","strategy":"Relaciona unidad con escala.","verification":"Expresarlo en metros sería poco práctico."},{"problem":"¿Qué unidad usarías para el largo de una sala?","steps":["La distancia es de varias unidades grandes.","El metro es apropiado."],"answer":"Metros","skill":"Argumentar","level":"Fundamental","strategy":"Elige una unidad que produzca un número manejable.","verification":"Centímetros darían un número innecesariamente grande."}]},"sort_order":8},{"lesson_id":"school-5b-oa-19","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Un lápiz empieza en 1,5 cm y termina en 15,2 cm.","steps":["No empieza en cero.","Restamos 15,2−1,5."],"answer":"13,7 cm","skill":"Resolver problemas","level":"Intermedio","strategy":"Usa lectura final menos inicial.","verification":"1,5+13,7=15,2."},{"problem":"Una regla tiene marcas cada 1 mm. ¿Puede justificar 8,347 cm exactos?","steps":["La mínima división es 1 mm=0,1 cm.","El instrumento no distingue milésimas de cm."],"answer":"No; su precisión no alcanza","skill":"Argumentar","level":"Intermedio","strategy":"Relaciona graduación con cifras reportadas.","verification":"Sería razonable registrar aproximadamente 8,3 cm."}]},"sort_order":9},{"lesson_id":"school-5b-oa-19","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Estima la altura de una puerta: 2 mm, 2 cm, 2 m o 20 m.","steps":["Una persona adulta mide cerca de 1,5–2 m.","Una puerta debe permitir su paso."],"answer":"Aproximadamente 2 m","skill":"Modelar","level":"Desafío","strategy":"Usa referentes cotidianos.","verification":"Las otras opciones son demasiado pequeñas o grandes."},{"problem":"Dos mediciones de una mesa son 119,8 cm y 120,1 cm. ¿Son necesariamente contradictorias?","steps":["La diferencia es 0,3 cm.","Puede deberse a precisión, posición o lectura."],"answer":"No; son mediciones cercanas","skill":"Argumentar","level":"Desafío","strategy":"Considera incertidumbre de medición.","verification":"Ambas sugieren cerca de 120 cm."}]},"sort_order":10},{"lesson_id":"school-5b-oa-19","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Elige unidad para una hormiga: mm, m o km.","hints":["Piensa en su tamaño."],"steps":["Una hormiga mide pocos milímetros."],"answer":"mm","skill":"Argumentar"},{"problem":"Un segmento inicia en 3 cm y termina en 11,4 cm.","hints":["Resta final−inicio."],"steps":["11,4−3=8,4."],"answer":"8,4 cm","skill":"Resolver problemas"},{"problem":"¿Por qué es importante escribir la unidad?","hints":["Compara “5 cm” y “5 m”."],"steps":["El número solo no indica la longitud real."],"answer":"Porque define la escala de la medida","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-19","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Comenzar siempre desde la marca observada como si fuera cero","description":"Si el objeto inicia en otra marca, hay que restarla."},{"title":"Omitir la unidad","description":"El resultado queda incompleto."},{"title":"Usar demasiadas cifras","description":"La precisión debe corresponder al instrumento."},{"title":"Elegir una unidad poco práctica","description":"La escala adecuada facilita interpretar la medida."}]},"sort_order":12},{"lesson_id":"school-5b-oa-19","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Eliges unidades adecuadas.","Lees instrumentos graduados.","Calculas longitudes con inicio no nulo.","Distingues estimación y medición.","Comunicas precisión y unidad."]},"sort_order":13},{"lesson_id":"school-5b-oa-19","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-20","block_type":"objective","title":"Meta de aprendizaje","content":"Convertir unidades de longitud y resolver problemas que combinan escalas diferentes.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-20","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Valor posicional","body":"Multiplicar o dividir por 10, 100 y 1000 desplaza la escala."},{"title":"Decimales","body":"Permiten expresar partes de una unidad mayor."},{"title":"Equivalencia","body":"Cambiar unidad no cambia la longitud real."}]},"sort_order":2},{"lesson_id":"school-5b-oa-20","block_type":"text","title":"Comprensión profunda","content":"Las unidades de longitud forman una escala. Un kilómetro equivale a 1000 metros; un metro a 100 centímetros; un centímetro a 10 milímetros.\n\nAl pasar a una unidad más pequeña, el número aumenta porque se necesitan más unidades para representar la misma longitud. Al pasar a una unidad mayor, el número disminuye.\n\nAntes de sumar o comparar medidas, deben expresarse en una unidad común. La comprobación principal es de magnitud: 3 km no pueden convertirse en 3 m, porque la unidad menor requiere un número mayor.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-20","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Kilómetro","body":"Unidad adecuada para distancias extensas."},{"title":"Metro","body":"Unidad base cotidiana."},{"title":"Centímetro","body":"Centésima parte de un metro."},{"title":"Milímetro","body":"Décima parte de un centímetro."}]},"sort_order":4},{"lesson_id":"school-5b-oa-20","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"unit_ladder","value":3.4,"from":"km","to":"m","result":3400,"caption":"Al pasar de kilómetros a metros se multiplica por 1000."},"sort_order":5},{"lesson_id":"school-5b-oa-20","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["1 km = 1000 m","1 m = 100 cm","1 cm = 10 mm","1 m = 1000 mm","A unidad menor: multiplica; a unidad mayor: divide"]},"sort_order":6},{"lesson_id":"school-5b-oa-20","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica origen y destino","body":"¿Qué unidad tienes y cuál necesitas?"},{"title":"2. Determina el factor","body":"Usa las equivalencias de la escala."},{"title":"3. Decide multiplicar o dividir","body":"Unidad menor aumenta el número."},{"title":"4. Calcula","body":"Cuida la coma decimal."},{"title":"5. Comprueba magnitud","body":"La longitud real debe permanecer igual."}]},"sort_order":7},{"lesson_id":"school-5b-oa-20","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Convierte 3,4 km a metros.","steps":["1 km=1000 m.","3,4·1000=3400."],"answer":"3400 m","skill":"Resolver problemas","level":"Fundamental","strategy":"A una unidad menor, multiplica.","verification":"3400 m÷1000=3,4 km."},{"problem":"Convierte 235 cm a metros y centímetros.","steps":["200 cm=2 m.","Quedan 35 cm."],"answer":"2 m 35 cm","skill":"Representar","level":"Fundamental","strategy":"Separa centenas de centímetros.","verification":"2·100+35=235 cm."}]},"sort_order":8},{"lesson_id":"school-5b-oa-20","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Convierte 1,75 m a centímetros.","steps":["1 m=100 cm.","1,75·100=175."],"answer":"175 cm","skill":"Resolver problemas","level":"Intermedio","strategy":"Dos posiciones decimales corresponden a centésimos de metro.","verification":"175÷100=1,75."},{"problem":"Convierte 4820 mm a metros.","steps":["1 m=1000 mm.","4820÷1000=4,82."],"answer":"4,82 m","skill":"Resolver problemas","level":"Intermedio","strategy":"A una unidad mayor, divide.","verification":"4,82·1000=4820."}]},"sort_order":9},{"lesson_id":"school-5b-oa-20","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Suma 2,3 m y 75 cm.","steps":["Convertimos 2,3 m=230 cm.","230+75=305 cm.","305 cm=3,05 m."],"answer":"3,05 m","skill":"Modelar","level":"Desafío","strategy":"Usa una unidad común antes de sumar.","verification":"3,05 m=305 cm."},{"problem":"Una ruta mide 1,2 km. Se recorren 850 m. ¿Cuánto falta?","steps":["1,2 km=1200 m.","1200−850=350 m."],"answer":"350 m","skill":"Modelar","level":"Desafío","strategy":"Convierte antes de restar.","verification":"850+350=1200 m."}]},"sort_order":10},{"lesson_id":"school-5b-oa-20","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Convierte 6 m a centímetros.","hints":["Cada metro contiene 100 cm."],"steps":["6·100=600."],"answer":"600 cm","skill":"Resolver problemas"},{"problem":"Convierte 45 mm a centímetros.","hints":["10 mm forman 1 cm.","Divide por 10."],"steps":["45÷10=4,5."],"answer":"4,5 cm","skill":"Resolver problemas"},{"problem":"Suma 1 m 20 cm y 85 cm.","hints":["Convierte todo a centímetros."],"steps":["1 m 20 cm=120 cm.","120+85=205 cm."],"answer":"205 cm o 2,05 m","skill":"Modelar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-20","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Mover la coma sin considerar el factor","description":"La cantidad de posiciones depende de la equivalencia."},{"title":"Multiplicar al pasar a unidad mayor","description":"En una unidad mayor se necesitan menos unidades."},{"title":"Sumar unidades diferentes","description":"Primero deben convertirse a una unidad común."},{"title":"No revisar magnitud","description":"Una conversión imposible suele cambiar la longitud real."}]},"sort_order":12},{"lesson_id":"school-5b-oa-20","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Usas equivalencias de longitud.","Decides multiplicar o dividir.","Conviertes números decimales.","Combinas medidas en problemas.","Compruebas la magnitud."]},"sort_order":13},{"lesson_id":"school-5b-oa-20","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-21","block_type":"objective","title":"Meta de aprendizaje","content":"Diseñar y comparar rectángulos utilizando perímetro y área, extrayendo conclusiones sobre sus dimensiones.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-21","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Multiplicación","body":"El área de un rectángulo se obtiene por filas y columnas."},{"title":"Suma","body":"El perímetro reúne las longitudes del borde."},{"title":"Unidades","body":"Perímetro usa unidades lineales; área, cuadradas."}]},"sort_order":2},{"lesson_id":"school-5b-oa-21","block_type":"text","title":"Comprensión profunda","content":"El perímetro mide la longitud del contorno. El área mide la superficie cubierta. Aunque ambos dependen de los lados, responden preguntas diferentes y usan unidades distintas.\n\nEn un rectángulo de largo l y ancho a, el perímetro es 2(l+a) y el área es l·a. Conocer una de estas medidas no siempre determina un único rectángulo: varios pares de lados pueden compartir perímetro o área.\n\nCuando el perímetro es fijo, los rectángulos más equilibrados tienden a tener mayor área. Analizar tablas de dimensiones ayuda a formular esta conclusión.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-21","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Perímetro","body":"Suma de las longitudes del borde."},{"title":"Área","body":"Cantidad de unidades cuadradas interiores."},{"title":"Dimensiones","body":"Largo y ancho del rectángulo."},{"title":"Restricción","body":"Condición fija, como perímetro 24."}]},"sort_order":4},{"lesson_id":"school-5b-oa-21","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"rectangle_perimeter_area","width":8,"height":5,"caption":"El mismo rectángulo tiene perímetro 26 unidades y área 40 unidades cuadradas."},"sort_order":5},{"lesson_id":"school-5b-oa-21","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["P=2(largo+ancho)","A=largo·ancho","Perímetro: unidades lineales","Área: unidades cuadradas","Con P fijo, lados más cercanos suelen aumentar A"]},"sort_order":6},{"lesson_id":"school-5b-oa-21","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica qué se pide","body":"Borde, superficie o dimensión faltante."},{"title":"2. Escribe datos y unidades","body":"Distingue largo y ancho."},{"title":"3. Selecciona relación","body":"Perímetro o área."},{"title":"4. Calcula y compara","body":"En diseño, prueba varios pares."},{"title":"5. Interpreta","body":"Comunica la conclusión y unidad correcta."}]},"sort_order":7},{"lesson_id":"school-5b-oa-21","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Rectángulo de 8 cm por 5 cm: perímetro.","steps":["P=2(8+5).","8+5=13.","2·13=26."],"answer":"26 cm","skill":"Resolver problemas","level":"Fundamental","strategy":"El perímetro recorre cuatro lados.","verification":"8+5+8+5=26."},{"problem":"Mismo rectángulo: área.","steps":["A=8·5."],"answer":"40 cm²","skill":"Resolver problemas","level":"Fundamental","strategy":"Área es filas por columnas.","verification":"Una cuadrícula tendría 40 cuadrados de 1 cm²."}]},"sort_order":8},{"lesson_id":"school-5b-oa-21","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Un rectángulo tiene perímetro 30 cm y largo 9 cm. ¿Ancho?","steps":["2(l+a)=30, por tanto l+a=15.","9+a=15.","a=6."],"answer":"6 cm","skill":"Resolver problemas","level":"Intermedio","strategy":"Primero divide el perímetro por 2.","verification":"2(9+6)=30."},{"problem":"Área 48 cm² y ancho 6 cm. ¿Largo?","steps":["l·6=48.","l=48÷6."],"answer":"8 cm","skill":"Resolver problemas","level":"Intermedio","strategy":"Usa la división como inversa.","verification":"8·6=48."}]},"sort_order":9},{"lesson_id":"school-5b-oa-21","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Perímetro 24: compara 2×10, 4×8, 5×7 y 6×6.","steps":["Todos suman lados 12 antes de duplicar.","Áreas:20,32,35,36."],"answer":"6×6 tiene mayor área","skill":"Argumentar","level":"Desafío","strategy":"Construye una tabla de pares y áreas.","verification":"El cuadrado tiene lados más equilibrados."},{"problem":"¿Dos rectángulos con área 36 tienen necesariamente igual perímetro?","steps":["Ejemplos: 4×9 y 6×6.","Perímetros:26 y 24."],"answer":"No","skill":"Argumentar","level":"Desafío","strategy":"Busca un contraejemplo.","verification":"Comparten área, pero sus bordes difieren."}]},"sort_order":10},{"lesson_id":"school-5b-oa-21","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Rectángulo 7 m por 3 m: calcula P y A.","hints":["Usa ambas fórmulas."],"steps":["P=2(7+3)=20.","A=7·3=21."],"answer":"P=20 m; A=21 m²","skill":"Resolver problemas"},{"problem":"P=22 cm y largo=7 cm. Halla ancho.","hints":["Divide P por 2.","Resta el largo."],"steps":["22÷2=11.","11−7=4."],"answer":"4 cm","skill":"Resolver problemas"},{"problem":"Da dos rectángulos de área 24.","hints":["Busca pares de factores de 24."],"steps":["3×8=24.","4×6=24."],"answer":"3×8 y 4×6","skill":"Representar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-21","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Confundir fórmulas","description":"El área multiplica lados; el perímetro suma el borde."},{"title":"Usar cm en el área","description":"El área requiere cm², m², etc."},{"title":"Sumar solo largo y ancho","description":"El perímetro incluye dos de cada uno."},{"title":"Suponer una única forma","description":"Una misma área o perímetro puede corresponder a varios rectángulos."}]},"sort_order":12},{"lesson_id":"school-5b-oa-21","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Distingues perímetro y área.","Usas unidades correctas.","Encuentras dimensiones faltantes.","Diseñas rectángulos con restricciones.","Comparas relaciones entre forma y área."]},"sort_order":13},{"lesson_id":"school-5b-oa-21","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-22","block_type":"objective","title":"Meta de aprendizaje","content":"Derivar y aplicar relaciones de área, y estimar superficies de figuras compuestas o irregulares.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-22","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Área de rectángulo","body":"Sirve como base para derivar otras fórmulas."},{"title":"Base y altura","body":"La altura es perpendicular a la base."},{"title":"Descomposición","body":"Una figura compleja puede separarse en piezas conocidas."}]},"sort_order":2},{"lesson_id":"school-5b-oa-22","block_type":"text","title":"Comprensión profunda","content":"Las fórmulas de área tienen sentido geométrico. Un paralelogramo puede cortarse y reorganizarse como un rectángulo de la misma base y altura. Un triángulo con base y altura dadas ocupa la mitad de ese rectángulo. Un trapecio puede emparejarse con una copia para formar un paralelogramo cuya base es la suma de sus bases.\n\nLa altura no siempre coincide con un lado inclinado: debe ser perpendicular a la base. En figuras compuestas se suman áreas; cuando hay una parte recortada, se resta.\n\nPara figuras irregulares en cuadrícula se cuentan cuadrados completos y se combinan partes aproximadas.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-22","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Base","body":"Lado elegido como referencia."},{"title":"Altura","body":"Distancia perpendicular a la base."},{"title":"Descomposición","body":"Separación en figuras conocidas."},{"title":"Conservación de área","body":"Reorganizar piezas sin solaparlas mantiene el área."}]},"sort_order":4},{"lesson_id":"school-5b-oa-22","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"shape_area","shape":"trapezoid","base1":8,"base2":4,"height":5,"caption":"El área del trapecio usa el promedio de sus bases multiplicado por la altura."},"sort_order":5},{"lesson_id":"school-5b-oa-22","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Paralelogramo: A=b·h","Triángulo: A=(b·h)/2","Trapecio: A=((B+b)·h)/2","Figura compuesta: suma o resta áreas","La altura debe ser perpendicular"]},"sort_order":6},{"lesson_id":"school-5b-oa-22","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Identifica figura y medidas","body":"Marca bases y altura."},{"title":"2. Comprueba perpendicularidad","body":"No uses automáticamente un lado inclinado."},{"title":"3. Elige o deriva la relación","body":"Relaciona con rectángulos o paralelogramos."},{"title":"4. Descompón si es necesario","body":"Suma y resta piezas."},{"title":"5. Revisa unidad y estimación","body":"El resultado debe ser razonable."}]},"sort_order":7},{"lesson_id":"school-5b-oa-22","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Paralelogramo de base 9 cm y altura 4 cm.","steps":["A=b·h.","9·4=36."],"answer":"36 cm²","skill":"Resolver problemas","level":"Fundamental","strategy":"La inclinación no afecta si base y altura se mantienen.","verification":"Puede reorganizarse como rectángulo 9×4."},{"problem":"Triángulo de base 10 m y altura 6 m.","steps":["A=(b·h)/2.","10·6=60.","60÷2=30."],"answer":"30 m²","skill":"Resolver problemas","level":"Fundamental","strategy":"Es la mitad del paralelogramo correspondiente.","verification":"Dos triángulos forman 60 m²."}]},"sort_order":8},{"lesson_id":"school-5b-oa-22","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Trapecio con bases 8 y 4, altura 5.","steps":["B+b=12.","12·5=60.","60÷2=30."],"answer":"30 u²","skill":"Resolver problemas","level":"Intermedio","strategy":"Promedia las bases o usa la fórmula completa.","verification":"Promedio de bases=6; 6·5=30."},{"problem":"Figura en L: rectángulo 8×6 menos recorte 3×2.","steps":["Área exterior=48.","Recorte=6.","48−6=42."],"answer":"42 u²","skill":"Modelar","level":"Intermedio","strategy":"Usa una figura grande y resta la parte ausente.","verification":"42 es menor que 48, como debe ser."}]},"sort_order":9},{"lesson_id":"school-5b-oa-22","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Un triángulo tiene área 24 cm² y base 8 cm. ¿Altura?","steps":["24=(8·h)/2.","48=8h.","h=6."],"answer":"6 cm","skill":"Resolver problemas","level":"Desafío","strategy":"Deshaz primero la división por 2.","verification":"(8·6)/2=24."},{"problem":"Dos paralelogramos tienen base 7 y altura 5, pero distinta inclinación.","steps":["Ambos usan las mismas medidas perpendiculares.","A=7·5 en ambos."],"answer":"Tienen igual área: 35 u²","skill":"Argumentar","level":"Desafío","strategy":"Distingue altura de lado inclinado.","verification":"La reorganización produce el mismo rectángulo."}]},"sort_order":10},{"lesson_id":"school-5b-oa-22","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Triángulo b=12, h=5.","hints":["Multiplica y divide por 2."],"steps":["12·5=60.","60÷2=30."],"answer":"30 u²","skill":"Resolver problemas"},{"problem":"Paralelogramo b=6, h=9.","hints":["Usa b·h."],"steps":["6·9=54."],"answer":"54 u²","skill":"Resolver problemas"},{"problem":"Trapecio B=10, b=6, h=4.","hints":["Suma bases.","Multiplica por altura y divide por 2."],"steps":["10+6=16.","16·4÷2=32."],"answer":"32 u²","skill":"Resolver problemas"}]},"sort_order":11},{"lesson_id":"school-5b-oa-22","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Usar lado inclinado como altura","description":"La altura debe formar 90° con la base."},{"title":"Olvidar dividir el triángulo por 2","description":"Ocupa la mitad del paralelogramo."},{"title":"Sumar dimensiones en vez de áreas","description":"Las piezas se combinan por su superficie."},{"title":"Omitir unidades cuadradas","description":"El área siempre se expresa en unidades²."}]},"sort_order":12},{"lesson_id":"school-5b-oa-22","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Calculas áreas básicas.","Identificas base y altura.","Explicas el origen de las fórmulas.","Descompones figuras compuestas.","Estimas y usas unidades cuadradas."]},"sort_order":13},{"lesson_id":"school-5b-oa-22","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-23","block_type":"objective","title":"Meta de aprendizaje","content":"Calcular promedios, reconstruir datos faltantes y comunicar qué representa el resultado.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-23","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Suma y división","body":"El promedio reúne el total y lo reparte entre los datos."},{"title":"Cantidad de datos","body":"Debe contarse correctamente."},{"title":"Contexto","body":"La unidad del promedio es la misma que la de los datos."}]},"sort_order":2},{"lesson_id":"school-5b-oa-23","block_type":"text","title":"Comprensión profunda","content":"El promedio o media aritmética se obtiene sumando los datos y dividiendo por su cantidad. Puede interpretarse como el valor que tendría cada dato si el total se repartiera equitativamente.\n\nEl promedio no tiene que coincidir con uno de los datos. Tampoco describe por sí solo toda la distribución: conjuntos muy distintos pueden compartirlo.\n\nSi se conoce el promedio y la cantidad de datos, la suma total se recupera multiplicando. Esto permite encontrar valores faltantes y analizar cómo cambia el promedio cuando se modifica un dato.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-23","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Suma total","body":"Cantidad acumulada por todos los datos."},{"title":"Frecuencia de datos","body":"Número de valores considerados."},{"title":"Media","body":"Suma total dividida por cantidad."},{"title":"Equilibrio","body":"Valor al que se nivelarían los datos conservando el total."}]},"sort_order":4},{"lesson_id":"school-5b-oa-23","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"mean_balance","values":[6,8,10,12],"mean":9,"caption":"Al redistribuir las cantidades sin cambiar el total, todas pueden nivelarse en 9."},"sort_order":5},{"lesson_id":"school-5b-oa-23","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Promedio = suma de datos / cantidad de datos","Suma total = promedio·cantidad","Dato faltante = suma total−suma conocida","La unidad del promedio se conserva","Un valor extremo puede mover el promedio"]},"sort_order":6},{"lesson_id":"school-5b-oa-23","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Cuenta datos","body":"Incluye todos y solo los pertinentes."},{"title":"2. Suma con orden","body":"Usa agrupaciones o una tabla."},{"title":"3. Divide","body":"Reparte el total entre la cantidad."},{"title":"4. Interpreta","body":"Explica qué significa en el contexto."},{"title":"5. Comprueba","body":"Promedio·cantidad debe recuperar la suma."}]},"sort_order":7},{"lesson_id":"school-5b-oa-23","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Promedio de 6,8,10,12.","steps":["Suma=36.","Hay 4 datos.","36÷4=9."],"answer":"9","skill":"Resolver problemas","level":"Fundamental","strategy":"Suma y divide por la cantidad.","verification":"9·4=36."},{"problem":"Promedio de 4,4,7.","steps":["Suma=15.","Hay 3 datos.","15÷3=5."],"answer":"5","skill":"Resolver problemas","level":"Fundamental","strategy":"El promedio puede no aparecer en los datos.","verification":"5·3=15."}]},"sort_order":8},{"lesson_id":"school-5b-oa-23","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"El promedio de 5 datos es 15. ¿Suma total?","steps":["Suma=promedio·cantidad.","15·5=75."],"answer":"75","skill":"Representar","level":"Intermedio","strategy":"Invierte la fórmula del promedio.","verification":"75÷5=15."},{"problem":"Promedio 15 de 5 números; cuatro suman 62.","steps":["Total=75.","Faltante=75−62=13."],"answer":"13","skill":"Resolver problemas","level":"Intermedio","strategy":"Recupera primero la suma total.","verification":"62+13=75."}]},"sort_order":9},{"lesson_id":"school-5b-oa-23","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Notas 5,5,6,6 y 7. Interpreta promedio.","steps":["Suma=29.","29÷5=5,8.","Representa la nota de equilibrio del conjunto."],"answer":"5,8","skill":"Modelar","level":"Desafío","strategy":"No lo presentes como una nota necesariamente obtenida.","verification":"5,8·5=29."},{"problem":"Dos grupos tienen promedio 10. ¿Deben tener los mismos datos?","steps":["Ejemplo A: 10,10.","Ejemplo B: 5,15.","Ambos promedian 10."],"answer":"No","skill":"Argumentar","level":"Desafío","strategy":"Usa un contraejemplo.","verification":"El promedio no describe la dispersión."}]},"sort_order":10},{"lesson_id":"school-5b-oa-23","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Promedio de 3,7 y 8.","hints":["Suma los tres.","Divide por 3."],"steps":["3+7+8=18.","18÷3=6."],"answer":"6","skill":"Resolver problemas"},{"problem":"Promedio 12 de 4 datos. ¿Suma?","hints":["Multiplica promedio por cantidad."],"steps":["12·4=48."],"answer":"48","skill":"Representar"},{"problem":"Promedio de 4 datos es 9; tres suman 25. Halla el cuarto.","hints":["Total=9·4.","Resta la suma conocida."],"steps":["Total=36.","36−25=11."],"answer":"11","skill":"Resolver problemas"}]},"sort_order":11},{"lesson_id":"school-5b-oa-23","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Dividir por un número equivocado","description":"Debe usarse la cantidad de datos."},{"title":"Confundir suma con promedio","description":"Después de sumar falta repartir."},{"title":"Suponer que debe ser un dato observado","description":"Puede ser un valor intermedio nuevo."},{"title":"Ignorar valores extremos","description":"Un dato muy alto o bajo modifica la media."}]},"sort_order":12},{"lesson_id":"school-5b-oa-23","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Calculas promedios.","Recuperas sumas totales.","Encuentras datos faltantes.","Interpretas como equilibrio.","Reconoces limitaciones del promedio."]},"sort_order":13},{"lesson_id":"school-5b-oa-23","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-24","block_type":"objective","title":"Meta de aprendizaje","content":"Describir cualitativamente la posibilidad de eventos y justificarla mediante resultados posibles.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-24","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Conjunto de resultados","body":"Antes de clasificar, identifica qué puede ocurrir."},{"title":"Condiciones","body":"La experiencia debe estar claramente definida."},{"title":"Lenguaje lógico","body":"Seguro e imposible son extremos distintos."}]},"sort_order":2},{"lesson_id":"school-5b-oa-24","block_type":"text","title":"Comprensión profunda","content":"Una experiencia aleatoria tiene resultados que no se conocen con certeza antes de realizarla, aunque sí pueden describirse sus posibilidades.\n\nUn evento es seguro si ocurre en todos los resultados posibles; imposible si no ocurre en ninguno. Entre ambos extremos hay eventos posibles, que pueden ser más o menos frecuentes según la composición de la experiencia.\n\nLa clasificación siempre depende de las condiciones. Obtener un número mayor que 6 es imposible en un dado común, pero no necesariamente en una ruleta numerada hasta 10.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-24","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Experimento aleatorio","body":"Proceso cuyo resultado particular no se conoce de antemano."},{"title":"Evento","body":"Resultado o grupo de resultados de interés."},{"title":"Seguro","body":"Ocurre en todos los casos."},{"title":"Imposible","body":"No puede ocurrir bajo las condiciones."}]},"sort_order":4},{"lesson_id":"school-5b-oa-24","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"probability_scale","events":[{"label":"Sacar 7 en dado","value":0},{"label":"Sacar par","value":0.5},{"label":"Sacar 1–6","value":1}],"caption":"La escala cualitativa va desde imposible hasta seguro."},"sort_order":5},{"lesson_id":"school-5b-oa-24","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Imposible: ningún resultado favorable","Seguro: todos los resultados favorables","Posible: al menos uno, pero no todos","La clasificación depende del experimento","Enumera resultados para justificar"]},"sort_order":6},{"lesson_id":"school-5b-oa-24","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Define experiencia","body":"Objeto, reglas y resultados posibles."},{"title":"2. Enumera resultados","body":"Evita decidir solo por intuición."},{"title":"3. Busca favorables","body":"Cuántos resultados cumplen el evento."},{"title":"4. Clasifica","body":"Seguro, posible, poco posible o imposible."},{"title":"5. Justifica","body":"Relaciona la categoría con los resultados."}]},"sort_order":7},{"lesson_id":"school-5b-oa-24","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"En un dado común, obtener un número del 1 al 6.","steps":["Todos los resultados posibles están entre 1 y 6."],"answer":"Evento seguro","skill":"Argumentar","level":"Fundamental","strategy":"Compara evento con todo el espacio de resultados.","verification":"No existe resultado que lo contradiga."},{"problem":"En un dado común, obtener 8.","steps":["Los resultados son 1,2,3,4,5,6.","8 no aparece."],"answer":"Evento imposible","skill":"Argumentar","level":"Fundamental","strategy":"Enumera los resultados.","verification":"No hay resultados favorables."}]},"sort_order":8},{"lesson_id":"school-5b-oa-24","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Bolsa con 9 azules y 1 roja: sacar roja.","steps":["Existe una ficha roja, por lo que puede ocurrir.","Es una entre diez, por lo que es poco posible."],"answer":"Posible, pero poco probable","skill":"Argumentar","level":"Intermedio","strategy":"Distingue imposible de poco frecuente.","verification":"Hay al menos un resultado favorable."},{"problem":"Moneda: obtener cara.","steps":["Cara es uno de los dos resultados.","No es seguro ni imposible."],"answer":"Posible","skill":"Argumentar","level":"Intermedio","strategy":"Evita afirmar certeza.","verification":"También puede salir sello."}]},"sort_order":9},{"lesson_id":"school-5b-oa-24","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Caja solo con lápices negros: sacar uno negro.","steps":["Todos los objetos cumplen la condición."],"answer":"Seguro","skill":"Modelar","level":"Desafío","strategy":"Revisa la composición completa.","verification":"Cualquier elección produce negro."},{"problem":"¿Puede el mismo evento cambiar de categoría si cambia la bolsa?","steps":["Sacar rojo es seguro en una bolsa solo roja.","Puede ser imposible en una bolsa sin rojo."],"answer":"Sí","skill":"Argumentar","level":"Desafío","strategy":"La probabilidad depende de las condiciones.","verification":"El nombre del evento no basta sin describir el experimento."}]},"sort_order":10},{"lesson_id":"school-5b-oa-24","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Dado común: obtener un número negativo.","hints":["Enumera 1 a 6."],"steps":["Ninguno es negativo."],"answer":"Imposible","skill":"Argumentar"},{"problem":"Ruleta con sectores rojo y azul: obtener azul.","hints":["Azul aparece entre los resultados.","También existe rojo."],"steps":["Puede ocurrir, pero no es seguro."],"answer":"Posible","skill":"Argumentar"},{"problem":"Bolsa con 20 verdes: sacar verde.","hints":["Todos los objetos son verdes."],"steps":["No hay otra posibilidad."],"answer":"Seguro","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-24","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Confundir poco posible con imposible","description":"Si existe al menos un resultado favorable, no es imposible."},{"title":"Usar seguro como sinónimo de muy probable","description":"Seguro significa que siempre ocurre."},{"title":"Ignorar las condiciones","description":"La misma pregunta cambia según el dado, bolsa o ruleta."},{"title":"No justificar","description":"La categoría debe apoyarse en resultados posibles."}]},"sort_order":12},{"lesson_id":"school-5b-oa-24","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Distingues seguro, posible e imposible.","Reconoces eventos poco posibles.","Enumeras resultados.","Consideras las condiciones.","Justificas categorías cualitativas."]},"sort_order":13},{"lesson_id":"school-5b-oa-24","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-25","block_type":"objective","title":"Meta de aprendizaje","content":"Ordenar probabilidades cualitativamente sin depender necesariamente de un cálculo formal.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-25","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Eventos posibles","body":"Debes identificar resultados favorables y totales."},{"title":"Fracciones simples","body":"Ayudan a comparar partes de un conjunto."},{"title":"Equidad","body":"Los objetos o sectores deben tener oportunidades comparables."}]},"sort_order":2},{"lesson_id":"school-5b-oa-25","block_type":"text","title":"Comprensión profunda","content":"Comparar probabilidades significa decidir qué evento tiene mayor posibilidad de ocurrir. En experiencias con resultados equiprobables, se compara la proporción de resultados favorables respecto del total.\n\nNo basta con contar favorables si los totales son distintos. Sacar una ficha roja de una bolsa con 2 rojas de 4 es más probable que de una bolsa con 3 rojas de 10, aunque la segunda tenga más fichas rojas.\n\nTambién es necesario revisar si los resultados son realmente equiprobables: sectores de distinto tamaño o objetos con propiedades diferentes pueden alterar la comparación.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-25","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Favorable","body":"Resultado que cumple el evento."},{"title":"Total","body":"Todos los resultados posibles."},{"title":"Equiprobable","body":"Cada resultado individual tiene igual posibilidad."},{"title":"Proporción","body":"Relación entre favorables y total."}]},"sort_order":4},{"lesson_id":"school-5b-oa-25","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"probability_bags","bags":[{"label":"A","red":2,"blue":2},{"label":"B","red":3,"blue":7}],"target":"roja","caption":"Aunque B tiene más rojas, A tiene mayor proporción de rojas."},"sort_order":5},{"lesson_id":"school-5b-oa-25","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Compara favorables/total","Más favorables con mismo total → más probable","Mismos favorables con mayor total → menos probable","Iguales proporciones → igual probabilidad","Verifica que los resultados sean equiprobables"]},"sort_order":6},{"lesson_id":"school-5b-oa-25","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Define evento","body":"Qué color, número o resultado se compara."},{"title":"2. Cuenta favorables y totales","body":"En cada experiencia."},{"title":"3. Forma una proporción","body":"Usa fracción, dibujo o razonamiento."},{"title":"4. Compara","body":"Mayor, menor o igual probabilidad."},{"title":"5. Revisa equidad","body":"Tamaños y condiciones deben ser comparables."}]},"sort_order":7},{"lesson_id":"school-5b-oa-25","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Bolsa A: 4 rojas y 6 azules; B: 2 rojas y 8 azules. ¿Dónde es más probable roja?","steps":["Ambas tienen 10 fichas.","A tiene más rojas."],"answer":"Bolsa A","skill":"Argumentar","level":"Fundamental","strategy":"Con el mismo total, compara favorables.","verification":"4/10>2/10."},{"problem":"Dos monedas equilibradas: cara y sello.","steps":["Hay dos resultados equiprobables.","Cada uno tiene una posibilidad de dos."],"answer":"Igualmente probables","skill":"Argumentar","level":"Fundamental","strategy":"Busca simetría y equilibrio.","verification":"Ambos tienen proporción 1/2."}]},"sort_order":8},{"lesson_id":"school-5b-oa-25","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"A: 2 rojas de 4; B: 3 rojas de 10.","steps":["A=1/2.","B=3/10.","1/2>3/10."],"answer":"A","skill":"Argumentar","level":"Intermedio","strategy":"No compares solo el número de rojas.","verification":"0,5>0,3."},{"problem":"Dado común: obtener par o obtener 6.","steps":["Pares:2,4,6 son tres resultados.","Obtener 6 es un resultado."],"answer":"Obtener par es más probable","skill":"Argumentar","level":"Intermedio","strategy":"Cuenta resultados favorables.","verification":"3 de 6 frente a 1 de 6."}]},"sort_order":9},{"lesson_id":"school-5b-oa-25","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Ruleta con sectores desiguales: 2 rojos pequeños y 1 azul grande. ¿Basta contar sectores?","steps":["Los sectores no tienen el mismo tamaño.","No son equiprobables."],"answer":"No","skill":"Argumentar","level":"Desafío","strategy":"Revisa el área de cada sector.","verification":"Un sector grande puede ser más probable que dos pequeños."},{"problem":"Diseña una bolsa donde rojo y azul sean igualmente probables.","steps":["Las proporciones deben ser iguales.","Puede usarse el mismo número de cada color."],"answer":"Ejemplo: 5 rojas y 5 azules","skill":"Modelar","level":"Desafío","strategy":"Construye cantidades equivalentes.","verification":"5/10=5/10."}]},"sort_order":10},{"lesson_id":"school-5b-oa-25","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"A:1 verde de 5; B:1 verde de 8. ¿Dónde es más probable verde?","hints":["Mismo número favorable.","Compara el total."],"steps":["Con menos objetos totales la proporción es mayor."],"answer":"Bolsa A","skill":"Argumentar"},{"problem":"Dado: obtener menor que 4 o mayor que 4.","hints":["Cuenta resultados en cada evento."],"steps":["Menor que 4:1,2,3 (3).","Mayor que 4:5,6 (2)."],"answer":"Menor que 4","skill":"Argumentar"},{"problem":"Bolsa 3 rojas y 3 azules. Compara colores.","hints":["Los conteos y el total son simétricos."],"steps":["3/6=3/6."],"answer":"Igualmente probables","skill":"Argumentar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-25","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Contar favorables sin considerar el total","description":"3 de 10 puede ser menos que 2 de 4."},{"title":"Suponer equiprobabilidad","description":"Sectores u objetos pueden no tener igual oportunidad."},{"title":"Confundir posible con más probable","description":"Ambos eventos pueden ser posibles y aun así diferir."},{"title":"No definir el evento","description":"La comparación debe indicar exactamente qué resultado interesa."}]},"sort_order":12},{"lesson_id":"school-5b-oa-25","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Comparas proporciones favorables.","Consideras el total.","Reconoces probabilidades iguales.","Revisas equiprobabilidad.","Diseñas experiencias con una condición dada."]},"sort_order":13},{"lesson_id":"school-5b-oa-25","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-26","block_type":"objective","title":"Meta de aprendizaje","content":"Interpretar datos, calcular cambios y formular conclusiones respaldadas por representaciones gráficas.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-26","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Escalas","body":"Cada marca del eje puede representar más de una unidad."},{"title":"Comparación","body":"Diferencias y totales se calculan desde los datos."},{"title":"Contexto","body":"Título, variables y unidades orientan la interpretación."}]},"sort_order":2},{"lesson_id":"school-5b-oa-26","block_type":"text","title":"Comprensión profunda","content":"Una tabla organiza datos en filas y columnas. Un gráfico de barras facilita comparar categorías; un gráfico de líneas muestra cómo cambia una variable ordenada, frecuentemente a través del tiempo.\n\nAntes de responder, deben revisarse título, etiquetas, unidades y escala. Una barra que mide el doble no siempre representa el doble si el eje está truncado o la escala no comienza en cero.\n\nUna conclusión válida se apoya en datos concretos y distingue observación de explicación. El gráfico puede mostrar que una cantidad aumentó, pero no siempre permite afirmar por qué.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-26","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Variable","body":"Característica que se registra."},{"title":"Categoría","body":"Grupo comparado en barras o tabla."},{"title":"Escala","body":"Valor representado por cada intervalo."},{"title":"Tendencia","body":"Patrón general de aumento, disminución o estabilidad."}]},"sort_order":4},{"lesson_id":"school-5b-oa-26","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"bar_line_chart","categories":["Lun","Mar","Mié","Jue","Vie"],"values":[12,18,15,22,20],"chart":"bar","caption":"Las etiquetas y la escala permiten comparar cantidades con precisión."},"sort_order":5},{"lesson_id":"school-5b-oa-26","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Total = suma de categorías","Cambio = valor final−valor inicial","Mayor/menor se identifica por valores, no solo apariencia","Revisa escala de los ejes","Una conclusión debe citar datos"]},"sort_order":6},{"lesson_id":"school-5b-oa-26","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Lee el título","body":"Identifica qué representa el gráfico."},{"title":"2. Revisa ejes y escala","body":"Determina unidades e intervalos."},{"title":"3. Extrae datos","body":"Anótalos si el problema requiere cálculos."},{"title":"4. Calcula o compara","body":"Total, diferencia, máximo o tendencia."},{"title":"5. Comunica con evidencia","body":"Incluye valores específicos en la conclusión."}]},"sort_order":7},{"lesson_id":"school-5b-oa-26","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Préstamos: lunes12, martes18, miércoles15. ¿Máximo?","steps":["Comparamos 12,18,15.","El mayor es 18."],"answer":"Martes","skill":"Representar","level":"Fundamental","strategy":"Lee los valores exactos.","verification":"18>15>12."},{"problem":"Una barra llega a 30 y otra a 22. ¿Diferencia?","steps":["Restamos 30−22."],"answer":"8 unidades","skill":"Resolver problemas","level":"Fundamental","strategy":"Diferencia es mayor menos menor.","verification":"22+8=30."}]},"sort_order":8},{"lesson_id":"school-5b-oa-26","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Una línea pasa de 40 a 55.","steps":["Cambio=final−inicial.","55−40=15."],"answer":"Aumento de 15","skill":"Resolver problemas","level":"Intermedio","strategy":"Distingue aumento de valor final.","verification":"40+15=55."},{"problem":"Ventas 8,12,10 y 15: total.","steps":["Sumamos todos los periodos.","8+12+10+15=45."],"answer":"45","skill":"Modelar","level":"Intermedio","strategy":"Evita usar solo máximo y mínimo.","verification":"La suma de categorías recupera el total."}]},"sort_order":9},{"lesson_id":"school-5b-oa-26","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Un gráfico parte su eje vertical en 90. ¿Puede exagerar diferencias?","steps":["Las barras no se comparan desde cero.","Pequeñas diferencias ocupan gran parte de la altura visible."],"answer":"Sí","skill":"Argumentar","level":"Desafío","strategy":"Revisa si el eje está truncado.","verification":"Los valores deben leerse, no inferirse solo por apariencia."},{"problem":"El gráfico muestra que subió la asistencia. ¿Prueba que fue por el clima?","steps":["El gráfico muestra asociación temporal.","No contiene información causal sobre el clima."],"answer":"No","skill":"Argumentar","level":"Desafío","strategy":"Distingue dato observado de explicación.","verification":"Se necesitaría información adicional."}]},"sort_order":10},{"lesson_id":"school-5b-oa-26","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Datos 5,9,7. ¿Máximo y mínimo?","hints":["Compara los tres valores."],"steps":["Máximo 9.","Mínimo 5."],"answer":"9 y 5","skill":"Representar"},{"problem":"Una cantidad baja de 70 a 52. ¿Cambio?","hints":["Resta final−inicial.","Interpreta el signo."],"steps":["52−70=−18."],"answer":"Disminuyó 18","skill":"Resolver problemas"},{"problem":"Barras A=14, B=20, C=16. ¿Total?","hints":["Suma las categorías."],"steps":["14+20+16=50."],"answer":"50","skill":"Modelar"}]},"sort_order":11},{"lesson_id":"school-5b-oa-26","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Ignorar la escala","description":"Una división del eje puede representar 2,5 o más unidades."},{"title":"Confundir total con máximo","description":"El total requiere sumar categorías."},{"title":"Afirmar causas no mostradas","description":"Un gráfico describe datos, no necesariamente explica motivos."},{"title":"Mirar solo la forma","description":"Los valores y etiquetas tienen prioridad."}]},"sort_order":12},{"lesson_id":"school-5b-oa-26","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Lees tablas y escalas.","Comparas categorías.","Calculas totales y cambios.","Identificas tendencias.","Comunicas conclusiones respaldadas."]},"sort_order":13},{"lesson_id":"school-5b-oa-26","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14},{"lesson_id":"school-5b-oa-27","block_type":"objective","title":"Meta de aprendizaje","content":"Organizar datos numéricos en tallos y hojas, recuperar valores y analizar distribución, extremos y rango.","data":{},"sort_order":1},{"lesson_id":"school-5b-oa-27","block_type":"prerequisites","title":"Antes de comenzar","content":"Revisa estas ideas antes de avanzar.","data":{"items":[{"title":"Valor posicional","body":"El tallo y la hoja separan posiciones del número."},{"title":"Orden","body":"Las hojas deben escribirse de menor a mayor."},{"title":"Rango","body":"Se obtiene restando máximo menos mínimo."}]},"sort_order":2},{"lesson_id":"school-5b-oa-27","block_type":"text","title":"Comprensión profunda","content":"Un diagrama de tallo y hojas organiza datos y, a diferencia de muchas gráficas, conserva cada valor individual. Para números de dos cifras, las decenas pueden ser tallos y las unidades hojas.\n\nLa clave es indispensable: 2|7 puede significar 27, 2,7 u otra escala según el contexto. Las hojas se ordenan para facilitar la lectura de mínimo, máximo, mediana y agrupamientos.\n\nSi un tallo no tiene datos puede mantenerse vacío cuando ayuda a conservar la continuidad de la escala.","data":{},"sort_order":3},{"lesson_id":"school-5b-oa-27","block_type":"concepts","title":"Conceptos fundamentales","content":"","data":{"items":[{"title":"Tallo","body":"Parte inicial compartida, como las decenas."},{"title":"Hoja","body":"Última cifra de cada dato."},{"title":"Clave","body":"Explica cómo reconstruir un valor."},{"title":"Distribución","body":"Muestra dónde se concentran o dispersan los datos."}]},"sort_order":4},{"lesson_id":"school-5b-oa-27","block_type":"math_model","title":"Modelo matemático visual","content":"","data":{"mode":"stem_leaf","stems":[{"stem":"1","leaves":[2,5,8]},{"stem":"2","leaves":[0,1,1,7]},{"stem":"3","leaves":[4]}],"key":"2|7 = 27","caption":"Cada hoja conserva un dato; las repeticiones deben mantenerse."},"sort_order":5},{"lesson_id":"school-5b-oa-27","block_type":"formula","title":"Relaciones y procedimientos","content":"","data":{"items":["Dato = tallo seguido de hoja, según la clave","Ordena hojas de menor a mayor","Repeticiones se escriben repetidas","Rango = máximo−mínimo","Cuenta de hojas = cantidad de datos"]},"sort_order":6},{"lesson_id":"school-5b-oa-27","block_type":"strategy","title":"Método MathLabs","content":"Aplica estos pasos antes de responder.","data":{"steps":[{"title":"1. Define la clave","body":"Decide qué posición será tallo y hoja."},{"title":"2. Separa cada dato","body":"Colócalo en el tallo correcto."},{"title":"3. Ordena hojas","body":"Conserva repeticiones."},{"title":"4. Verifica cantidad","body":"El número de hojas debe igualar los datos."},{"title":"5. Interpreta","body":"Lee extremos, rango y concentraciones."}]},"sort_order":7},{"lesson_id":"school-5b-oa-27","block_type":"examples","title":"Ejercicios resueltos: nivel fundamental","content":"","data":{"examples":[{"problem":"Con clave 2|7=27, ¿qué valor representa 3|4?","steps":["El tallo representa decenas.","La hoja representa unidades."],"answer":"34","skill":"Representar","level":"Fundamental","strategy":"Usa la clave.","verification":"3 decenas y 4 unidades forman 34."},{"problem":"Datos 12,15,18. Construye fila.","steps":["Todos tienen tallo 1.","Hojas 2,5,8 ya ordenadas."],"answer":"1 | 2 5 8","skill":"Representar","level":"Fundamental","strategy":"Separa decenas y unidades.","verification":"Se recuperan 12,15,18."}]},"sort_order":8},{"lesson_id":"school-5b-oa-27","block_type":"examples","title":"Ejercicios resueltos: nivel intermedio","content":"","data":{"examples":[{"problem":"Diagrama 2|0 3 7; 3|1 5. ¿Máximo?","steps":["La última hoja del tallo mayor es 5.","Representa 35."],"answer":"35","skill":"Representar","level":"Intermedio","strategy":"Busca tallo y hoja mayores.","verification":"Los datos son 20,23,27,31,35."},{"problem":"Mismo diagrama: rango.","steps":["Mínimo=20.","Máximo=35.","35−20=15."],"answer":"15","skill":"Resolver problemas","level":"Intermedio","strategy":"Recupera primero extremos.","verification":"20+15=35."}]},"sort_order":9},{"lesson_id":"school-5b-oa-27","block_type":"examples","title":"Ejercicios resueltos: desafío","content":"","data":{"examples":[{"problem":"Datos 21,21,24. ¿Cómo aparecen repeticiones?","steps":["Cada dato debe conservarse.","La hoja 1 se escribe dos veces."],"answer":"2 | 1 1 4","skill":"Representar","level":"Desafío","strategy":"No elimines valores repetidos.","verification":"Hay tres hojas para tres datos."},{"problem":"Un diagrama tiene 12 hojas. ¿Cuántos datos contiene?","steps":["Cada hoja representa un valor individual."],"answer":"12 datos","skill":"Argumentar","level":"Desafío","strategy":"Cuenta hojas, incluyendo repeticiones.","verification":"El tallo no cuenta como dato por sí solo."}]},"sort_order":10},{"lesson_id":"school-5b-oa-27","block_type":"guided_practice","title":"Práctica guiada","content":"Intenta antes de abrir las pistas.","data":{"exercises":[{"problem":"Clave 4|2=42. Lee 5|7.","hints":["Tallo=decenas, hoja=unidades."],"steps":["5 decenas y 7 unidades."],"answer":"57","skill":"Representar"},{"problem":"Construye para 31,34,39.","hints":["Todos comparten tallo 3.","Ordena hojas."],"steps":["Hojas 1,4,9."],"answer":"3 | 1 4 9","skill":"Representar"},{"problem":"Diagrama 1|4 8; 2|0 6. Halla rango.","hints":["Mínimo 14, máximo 26."],"steps":["26−14=12."],"answer":"12","skill":"Resolver problemas"}]},"sort_order":11},{"lesson_id":"school-5b-oa-27","block_type":"common_errors","title":"Errores frecuentes","content":"","data":{"items":[{"title":"Omitir la clave","description":"Sin ella no se conoce la escala de los datos."},{"title":"Eliminar repeticiones","description":"Cada observación debe conservarse."},{"title":"Desordenar hojas","description":"Dificulta leer extremos y distribución."},{"title":"Contar tallos como datos","description":"La cantidad de datos corresponde a las hojas."}]},"sort_order":12},{"lesson_id":"school-5b-oa-27","block_type":"summary","title":"Dominio esperado","content":"","data":{"items":["Construyes tallos y hojas.","Usas una clave correcta.","Conservas datos repetidos.","Recuperas valores individuales.","Analizas mínimo, máximo y rango."]},"sort_order":13},{"lesson_id":"school-5b-oa-27","block_type":"practice","title":"Practica este tema","content":"Realiza una sesión segura de ocho preguntas para actualizar tu dominio.","data":{},"sort_order":14}]$blocks$::jsonb)
as x(lesson_id text,block_type text,title text,content text,data jsonb,sort_order integer);

