from jsonb_to_recordset($practice$[{"code":"P5-C14-001","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"¿Cuál es el siguiente término de 4, 9, 14, 19, …?","options":[{"id":"A","text":"22"},{"id":"B","text":"23"},{"id":"C","text":"24"},{"id":"D","text":"29"}],"correct_option":"C","explanation":"La diferencia constante es 5; 19+5=24.","feedback_by_option":{"A":"Revisa esta alternativa. La diferencia constante es 5; 19+5=24.","B":"Revisa esta alternativa. La diferencia constante es 5; 19+5=24.","C":"Correcto. La diferencia constante es 5; 19+5=24.","D":"Revisa esta alternativa. La diferencia constante es 5; 19+5=24."},"difficulty":"Fundamental","skill":"Resolver problemas","sort_order":2001,"is_published":true},{"code":"P5-C14-002","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"La sucesión 30, 26, 22, 18 disminuye siempre en:","options":[{"id":"A","text":"2"},{"id":"B","text":"4"},{"id":"C","text":"6"},{"id":"D","text":"8"}],"correct_option":"B","explanation":"Cada término se obtiene restando 4.","feedback_by_option":{"A":"Revisa esta alternativa. Cada término se obtiene restando 4.","B":"Correcto. Cada término se obtiene restando 4.","C":"Revisa esta alternativa. Cada término se obtiene restando 4.","D":"Revisa esta alternativa. Cada término se obtiene restando 4."},"difficulty":"Fundamental","skill":"Resolver problemas","sort_order":2002,"is_published":true},{"code":"P5-C14-003","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"Una sucesión parte en 7 y aumenta 3. ¿Cuál es el quinto término?","options":[{"id":"A","text":"16"},{"id":"B","text":"19"},{"id":"C","text":"22"},{"id":"D","text":"25"}],"correct_option":"B","explanation":"Hay cuatro aumentos: 7+4·3=19.","feedback_by_option":{"A":"Revisa esta alternativa. Hay cuatro aumentos: 7+4·3=19.","B":"Correcto. Hay cuatro aumentos: 7+4·3=19.","C":"Revisa esta alternativa. Hay cuatro aumentos: 7+4·3=19.","D":"Revisa esta alternativa. Hay cuatro aumentos: 7+4·3=19."},"difficulty":"Intermedio","skill":"Resolver problemas","sort_order":2003,"is_published":true},{"code":"P5-C14-004","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"¿Qué regla describe 5, 10, 15, 20?","options":[{"id":"A","text":"Sumar 4"},{"id":"B","text":"Sumar 5"},{"id":"C","text":"Duplicar"},{"id":"D","text":"Restar 5"}],"correct_option":"B","explanation":"Cada término aumenta en 5.","feedback_by_option":{"A":"Revisa esta alternativa. Cada término aumenta en 5.","B":"Correcto. Cada término aumenta en 5.","C":"Revisa esta alternativa. Cada término aumenta en 5.","D":"Revisa esta alternativa. Cada término aumenta en 5."},"difficulty":"Fundamental","skill":"Resolver problemas","sort_order":2004,"is_published":true},{"code":"P5-C14-005","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"¿Cuál término no pertenece a la regla sumar 6: 2,8,14,21,26?","options":[{"id":"A","text":"8"},{"id":"B","text":"14"},{"id":"C","text":"21"},{"id":"D","text":"26"}],"correct_option":"C","explanation":"Después de 14 debería venir 20, no 21.","feedback_by_option":{"A":"Revisa esta alternativa. Después de 14 debería venir 20, no 21.","B":"Revisa esta alternativa. Después de 14 debería venir 20, no 21.","C":"Correcto. Después de 14 debería venir 20, no 21.","D":"Revisa esta alternativa. Después de 14 debería venir 20, no 21."},"difficulty":"Intermedio","skill":"Argumentar","sort_order":2005,"is_published":true},{"code":"P5-C14-006","course_id":"cl-5-basico","topic_id":"topic-ma05-oa-14","prompt":"Paso 1 tiene 3 cuadrados y cada paso agrega 2. ¿Cuántos hay en paso 6?","options":[{"id":"A","text":"11"},{"id":"B","text":"13"},{"id":"C","text":"15"},{"id":"D","text":"18"}],"correct_option":"B","explanation":"Desde paso 1 al 6 hay cinco aumentos:3+5·2=13.","feedback_by_option":{"A":"Revisa esta alternativa. Desde paso 1 al 6 hay cinco aumentos:3+5·2=13.","B":"Correcto. Desde paso 1 al 6 hay cinco aumentos:3+5·2=13.","C":"Revisa esta alternativa. Desde paso 1 al 6 