create or replace function public.start_school_diagnostic(p_course_id text default 'cl-5-basico')
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_session uuid;
  v_total integer;
  v_version text := case when p_course_id = 'cl-5-basico' then '5b-v2' else '5b-v1' end;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  if not exists (select 1 from public.courses where id=p_course_id and is_published=true) then
    raise exception 'Curso no válido';
  end if;
  update public.school_diagnostic_sessions set status='abandoned',updated_at=now()
  where user_id=v_user and course_id=p_course_id and status='started';
  select count(*) into v_total from public.school_diagnostic_items
  where course_id=p_course_id and diagnostic_version=v_version and is_published=true;
  if v_total < 8 then raise exception 'El diagnóstico todavía no tiene suficientes preguntas publicadas'; end if;
  insert into public.school_diagnostic_sessions (user_id,course_id,status,total_questions,correct_answers,result_summary,diagnostic_version,answered_questions,score_percent,started_at,updated_at)
  values (v_user,p_course_id,'started',v_total,0,'{}'::jsonb,v_version,0,0,now(),now()) returning id into v_session;
  insert into public.school_diagnostic_session_items (session_id,item_id,position)
  select v_session,id,row_number() over(order by sort_order,code)::integer
  from public.school_diagnostic_items
  where course_id=p_course_id and diagnostic_version=v_version and is_published=true
  order by sort_order,code;
  return jsonb_build_object('session_id',v_session,'course_id',p_course_id,'total_questions',v_total,'diagnostic_version',v_version);
end;
$$;

revoke all on function public.start_school_diagnostic(text) from public,anon,authenticated;
grant execute on function public.start_school_diagnostic(text) to authenticated;

commit;
